import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check if any clinical/cohort variable shows strong association with outcome
    clinical_effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            y1 = feats.x[feats.y == 1, i]
            y0 = feats.x[feats.y == 0, i]
            tstat, _ = stats.ttest_ind(y1, y0, equal_var=False)
            if abs(tstat) > 2.0:
                clinical_effects.append((fid, abs(tstat)))

    # If we found a strong clinical/cohort variable, use it as driver
    if clinical_effects:
        clinical_effects.sort(key=lambda x: x[1], reverse=True)
        drivers = [clinical_effects[0][0]]
        # Select top features for regression, avoiding near-duplicates
        columns = []
        used = set()
        for i, fid in enumerate(feats.ids):
            if len(columns) >= 5:
                break
            if fid in used:
                continue
            # Check correlation with already selected features
            is_correlated = False
            for selected_fid in columns:
                corr = np.corrcoef(feats.x[:, feats.column(fid)], 
                                  feats.x[:, feats.column(selected_fid)])[0,1]
                if abs(corr) > 0.6:
                    is_correlated = True
                    break
            if not is_correlated:
                columns.append(fid)
                used.add(fid)
        return Design(
            drivers=tuple(drivers),
            columns=tuple(columns),
            products=(),
            loadings={}
        )

    # No strong clinical driver found; look for direct associations
    # Compute effect sizes using Welch's t-test
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        y1 = feats.x[feats.y == 1, i]
        y0 = feats.x[feats.y == 0, i]
        tstat, _ = stats.ttest_ind(y1, y0, equal_var=False)
        effect_sizes.append((fid, abs(tstat)))

    # Sort by effect size
    effect_sizes.sort(key=lambda x: x[1], reverse=True)

    # Select top features for logistic regression
    columns = tuple(f[0] for f in effect_sizes[:5])

    # Use top feature as driver if we have any
    drivers = (effect_sizes[0][0],) if effect_sizes else ()

    # Simple weighted score based on top features
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if fid in columns:
            # Weight by effect size
            effect = 0
            for f, e in effect_sizes:
                if f == fid:
                    effect = e
                    break
            loadings[fid] = effect

    return Design(
        drivers=drivers,
        columns=columns,
        products=(),
        loadings=loadings
    )

